// Melyik ligakat figyeljuk, es mi a sajat konyvunk.
//
// A 'myBook' az a konyv, ahol alapbol fogadnal. A rendszer ehhez kepest
// mutatja meg, mennyit veszitesz azzal, hogy ott fogadsz.
// The Odds API bookmaker kulcsok: pinnacle, bet365, unibet_eu, betano,
// williamhill, marathonbet, onexbet, betfair_ex_eu, nordicbet, betsson...
//
// FONTOS: a tippmixpro nincs a The Odds API-ban (magyar allami monopol konyv).
// Ezert a 'myBook' egy hozza hasonlo, szinten magas margoju konyv - proxykent.
// Ha van Bet365 vagy Unibet fiokod, allitsd arra, es a szam pontos lesz.

const LEAGUES = [
  { key: 'soccer_epl',            name: 'Premier League' },
  { key: 'soccer_spain_la_liga',  name: 'La Liga' },
  { key: 'soccer_germany_bundesliga', name: 'Bundesliga' },
  { key: 'soccer_italy_serie_a',  name: 'Serie A' },
  { key: 'soccer_france_ligue_one', name: 'Ligue 1' },
];

const CONFIG = {
  myBook: 'bet365',        // a te alapertelmezett konyved
  minGapPct: 2.0,          // ennyi % arkulonbseg felett szol
  minOdds: 1.5,            // ez alatt nem erdekes
  maxOdds: 6.0,            // e felett tul nagy a variancia
  maxHoursAhead: 96,       // ennyi oran belul kezdodo meccsek
};

return LEAGUES.map(l => ({ json: { ...l, config: CONFIG } }));

// Ar-osszehasonlitas. Ez a rendszer lenyege - es itt nincs semmilyen jóslas.
//
// Minden meccs minden kimenetelere:
//   - melyik konyv adja a legjobb arat
//   - mennyivel jobb ez az atlagnal (ez a te nyeresegеd, ha ott fogadsz)
//   - mennyivel rosszabb a sajat konyved (ez amit most veszitesz)
//   - mennyi a piac margoja (ha tul magas, az egesz meccs kerulendo)

const out = [];
const errors = [];
let totalEvents = 0;

for (const item of $input.all()) {
  const j = item.json;

  // A fullResponse miatt a valasz {statusCode, body, headers} alakban jon.
  const status = j.statusCode;
  const body = j.body !== undefined ? j.body : j;
  const league = j.name || ($('League Config').first().json.name) || 'ismeretlen';
  const cfg = ($('League Config').first().json.config) || {};

  if (status && status !== 200) {
    errors.push(`${league}: HTTP ${status} - ${typeof body === 'object' ? JSON.stringify(body).slice(0,120) : String(body).slice(0,120)}`);
    continue;
  }
  if (!Array.isArray(body)) {
    errors.push(`${league}: varatlan valasz forma`);
    continue;
  }

  for (const ev of body) {
    totalEvents++;
    if (!ev.bookmakers || ev.bookmakers.length < 3) continue;

    const kickoff = new Date(ev.commence_time);
    const hoursAhead = (kickoff - new Date()) / 3600000;
    if (hoursAhead < 0 || hoursAhead > (cfg.maxHoursAhead || 96)) continue;

    // kimenetel -> [{book, price}]
    const byOutcome = {};
    for (const bk of ev.bookmakers) {
      const mk = (bk.markets || []).find(m => m.key === 'h2h');
      if (!mk || !mk.outcomes) continue;
      for (const oc of mk.outcomes) {
        const price = Number(oc.price);
        if (!Number.isFinite(price) || price <= 1) continue;
        (byOutcome[oc.name] = byOutcome[oc.name] || []).push({ book: bk.key, title: bk.title, price });
      }
    }

    // piaci margo: a legjobb arakbol szamolva (ez a valos elerheto piac)
    const names = Object.keys(byOutcome);
    if (names.length < 2) continue;
    let bestSum = 0;
    for (const n of names) bestSum += 1 / Math.max(...byOutcome[n].map(o => o.price));
    const marketMarginPct = (bestSum - 1) * 100;

    for (const name of names) {
      const quotes = byOutcome[name];
      if (quotes.length < 3) continue;

      const prices = quotes.map(q => q.price);
      const best = quotes.reduce((a, b) => (b.price > a.price ? b : a));
      const avg = prices.reduce((a, b) => a + b, 0) / prices.length;
      const mine = quotes.find(q => q.book === cfg.myBook);

      if (best.price < (cfg.minOdds || 1.5) || best.price > (cfg.maxOdds || 6)) continue;

      const gapVsAvgPct = (best.price / avg - 1) * 100;
      const gapVsMinePct = mine ? (best.price / mine.price - 1) * 100 : null;

      out.push({
        json: {
          league,
          event_id: ev.id,
          match_name: `${ev.home_team} vs ${ev.away_team}`,
          kickoff: ev.commence_time,
          hours_ahead: Math.round(hoursAhead * 10) / 10,
          selection: name,
          best_odds: Math.round(best.price * 1000) / 1000,
          best_book: best.title || best.book,
          avg_odds: Math.round(avg * 1000) / 1000,
          my_odds: mine ? mine.price : null,
          my_book: cfg.myBook,
          gap_vs_avg_pct: Math.round(gapVsAvgPct * 100) / 100,
          gap_vs_mine_pct: gapVsMinePct === null ? null : Math.round(gapVsMinePct * 100) / 100,
          market_margin_pct: Math.round(marketMarginPct * 100) / 100,
          book_count: quotes.length,
          // a dontesi mezo: ha van sajat konyv adat, ahhoz merunk, kulonben az atlaghoz
          gap_pct: Math.round((gapVsMinePct === null ? gapVsAvgPct : gapVsMinePct) * 100) / 100,
        }
      });
    }
  }
}

if (out.length === 0) {
  return [{ json: { _summary: true, events: totalEvents, opportunities: 0, errors } }];
}
out.push({ json: { _summary: true, events: totalEvents, opportunities: out.length, errors } });
return out;

// Hibaag: a HTTP node hibas kimenete ide fut. Nem nyeljuk el csendben.
const msgs = $input.all().map(i => {
  const e = i.json.error || i.json;
  return typeof e === 'object' ? JSON.stringify(e).slice(0, 200) : String(e).slice(0, 200);
});
return [{ json: { _summary: true, events: 0, opportunities: 0, errors: msgs.length ? msgs : ['ismeretlen HTTP hiba'] } }];

// Szures + rangsorolas + uzenet osszeallitas.
// Egyetlen Telegram uzenet megy ki, nem fogadasonkent egy.

const all = $input.all().map(i => i.json);
const summaries = all.filter(x => x._summary);
const rows = all.filter(x => !x._summary);

const cfg = (() => { try { return $('League Config').first().json.config; } catch (e) { return {}; } })();
const minGap = cfg.minGapPct !== undefined ? cfg.minGapPct : 2.0;
const myBook = cfg.myBook || 'bet365';

const events = summaries.reduce((a, s) => a + (s.events || 0), 0);
const errors = summaries.flatMap(s => s.errors || []);

// csak az erdemi resek, legjobb elol
const hits = rows
  .filter(r => r.gap_pct >= minGap)
  .sort((a, b) => b.gap_pct - a.gap_pct)
  .slice(0, 12);

const fmtTime = iso => {
  try {
    return new Date(iso).toLocaleString('hu-HU', {
      timeZone: 'Europe/Budapest', month: 'numeric', day: 'numeric',
      hour: '2-digit', minute: '2-digit'
    });
  } catch (e) { return iso; }
};

let msg;
if (hits.length === 0) {
  msg = `📊 Ar-ellenorzes kesz\n\n${events} meccs atnezve, nincs ${minGap}%-nal nagyobb arkulonbseg.\n\nEz normalis — ha most fogadnal, a sajat konyved ara kozel van a piachoz.`;
} else {
  const lines = hits.map(h => {
    const mine = h.my_odds
      ? `${myBook}: ${h.my_odds.toFixed(2)}`
      : `piaci atlag: ${h.avg_odds.toFixed(2)}`;
    const warn = h.market_margin_pct > 8 ? '  ⚠️ magas margo' : '';
    return `${h.match_name}\n  ${fmtTime(h.kickoff)} · ${h.league}\n  ${h.selection}\n  ✅ ${h.best_book}: ${h.best_odds.toFixed(2)}  (${mine})\n  → +${h.gap_pct.toFixed(1)}% jobb ar${warn}`;
  });

  const avgGap = hits.reduce((a, h) => a + h.gap_pct, 0) / hits.length;
  msg = `💰 ARKULONBSEGEK\n\n${lines.join('\n\n')}\n\n──────────\n${hits.length} lehetoseg, atlag +${avgGap.toFixed(1)}%\n${events} meccs atnezve\n\nEz nem tipp. Ha amugy is fogadnal ezekre, itt jobb aron teheted.`;
}

if (errors.length) {
  msg += `\n\n⚠️ Hibak:\n${errors.slice(0, 3).join('\n')}`;
}

return [{ json: { message: msg, hit_count: hits.length, events_checked: events, error_count: errors.length } }];
